def get_median(sorted_values):
    length = len(sorted_values)
    if length % 2 == 0:
        mid1 = sorted_values[length // 2 - 1]
        mid2 = sorted_values[length // 2]
        return (mid1 + mid2) // 2
    else:
        return sorted_values[length // 2]

def get_sorted_values(a, b, c):
